#!/usr/bin/env python3
import cadquery as cq
from pathlib import Path

SPEC = {'kind': 'extrusion', 'center': [0.19920496, -0.01090888000000001, 0.018018775], 'basis': [[0.0, 0.8940351237152316, -0.44799687226976337], [-0.001278865273789237, 0.4479965059209803, 0.8940343926193247], [0.9999991822514714, 0.0005729276427119928, 0.0011433504732672741]], 'axis': [-0.44799687226976337, 0.8940343926193247, 0.0011433504732672741], 'zmin': -0.218493836728714, 'zmax': 0.21849384260226196, 'profiles': [{'outer': [[-0.04046830620777568, -0.004423839238052191], [-0.0407870408863044, 6.927463002268226e-05], [-0.04047883089810804, 0.004558358482348635], [-0.040166544071490874, 0.006855587639843432], [-0.039359623169004196, 0.010734114166546491], [-0.03957155371689864, 0.011331203056349257], [-0.04045733552628725, 0.015538955892466295], [-0.04076202447363765, 0.017838148737482934], [-0.04108074912659725, 0.022331289412761933], [-0.04063414114826411, 0.028978779522011038], [-0.04032185433443559, 0.03127603104017341], [-0.039446227558637324, 0.035484748315434494], [-0.038097541756357635, 0.0393125589059733], [-0.03735246330875887, 0.04118278467592005], [-0.035774504787867395, 0.04442269141699829], [-0.03313272690774362, 0.04851540728146381], [-0.03142949978024226, 0.05073627254536543], [-0.028906608733050898, 0.053472971412805236], [-0.02737681183286042, 0.0549422278270525], [-0.025322864214050084, 0.056660568541831116], [-0.02291069824524005, 0.05841929090833161], [-0.020095493052883613, 0.06015361067166499], [-0.01684733484674802, 0.06179014816358378], [-0.013166182855873723, 0.06323062793488544], [-0.009101712252271145, 0.06437031614326075], [-0.00473847179862453, 0.0651019897317081], [-0.00020576276670040313, 0.06535661620489641], [0.004322260791968667, 0.06510718088011752], [0.008686383201528078, 0.06438050744319135], [0.012752195949392812, 0.06324547730270032], [0.01643505794939065, 0.06180918528099932], [0.019685154442101158, 0.06017636634189905], [0.022502434643784312, 0.05844527358778392], [0.024916674715395947, 0.0566893208849526], [0.02697266374847688, 0.054973357209498516], [0.028507884341870807, 0.05350585682993471], [0.03103033918164055, 0.0507720172819583], [0.032740439262893606, 0.048553107609167374], [0.03538284704884259, 0.04446345050424096], [0.036969425952941844, 0.04122535233564013], [0.03770710626724096, 0.039355958218761256], [0.0390651982514959, 0.03552972523836094], [0.03995097003531538, 0.031321990296795985], [0.040255662716952384, 0.02902509226353063], [0.040574392216076755, 0.02453637654281227], [0.040127789404359314, 0.017884483825820478], [0.0398154988562442, 0.015584910674853132], [0.03900856976492063, 0.011706377743613024], [0.03927801551483274, 0.010930762622487593], [0.040163787273074916, 0.006723045581203975], [0.04046847996750057, 0.00442613412762234], [0.04078720947941358, -6.257713270987374e-05], [0.040479004645044274, -0.004556059112813444], [0.04016671409692916, -0.006855641204132046], [0.039291087333919554, -0.011064354019006982], [0.0379424014932739, -0.014892151169650572], [0.037197323032886476, -0.016762390340334735], [0.035619354537580486, -0.020002288166369925], [0.03297757661909076, -0.024094990590940273], [0.03127434950437805, -0.026315833513753217], [0.028751458469975344, -0.029052608383968], [0.027221661595362167, -0.030521864817794155], [0.02516771393818587, -0.03224016527162386], [0.022755548007741797, -0.03399886531661456], [0.019940342789808056, -0.03573320294107158], [0.01669218458367246, -0.03736974043299034], [0.013011022631172302, -0.03881023364991647], [0.00894656196361828, -0.03994988157203473], [0.0045833115483458016, -0.040681586486808995], [5.558252513794086e-05, -0.04093622352713393], [-0.004477421042247395, -0.04068677763521842], [-0.008841543490172764, -0.03996007287769461], [-0.012907356174094236, -0.038825083017731334], [-0.016590228199661203, -0.03738879098218075], [-0.019840324679583056, -0.0357559675826943], [-0.022657594894063035, -0.034024870342884844], [-0.025071844978455153, -0.0322689131658177], [-0.027127823960389645, -0.030552967404494612], [-0.0286630545793527, -0.029085458070729958], [-0.03118550941912245, -0.026351609582402284], [-0.032895609513164156, -0.024132704369997548], [-0.035538017311901794, -0.020043015964052387], [-0.03712459619042374, -0.01680495357643535], [-0.03786227651751151, -0.014935563919942692], [-0.03927784546381714, -0.010930798325652554], [-0.04016361726042528, -0.006723067844473765]], 'holes': []}], 'simplify_tolerance': 2.125856794640607e-05, 'sketch_entity_count': 89}
OUT = Path(__file__).resolve().parent

def vec(v):
    return cq.Vector(float(v[0]), float(v[1]), float(v[2]))

def build():
    s = SPEC
    kind = s["kind"]
    B = s.get("basis")
    center = s.get("center")
    if kind == "extrusion":
        xdir = [B[i][0] for i in range(3)]
        axis = [B[i][2] for i in range(3)]
        origin = [center[i] + s["zmin"] * axis[i] for i in range(3)]
        plane = cq.Plane(origin=origin, xDir=xdir, normal=axis)
        result = None
        height = s["zmax"] - s["zmin"]
        for profile in s["profiles"]:
            solid = cq.Workplane(plane).polyline(profile["outer"]).close().extrude(height)
            for hole in profile["holes"]:
                cutter = cq.Workplane(plane).polyline(hole).close().extrude(height)
                solid = solid.cut(cutter)
            result = solid if result is None else result.union(solid)
    elif kind == "multi_loft":
        def loft(track):
            wires = [cq.Wire.makePolygon([vec(p) for p in section], close=True) for section in track]
            return cq.Solid.makeLoft(wires, ruled=bool(s.get("ruled", True)))
        outer = [loft(track) for track in s["outer_tracks"]]
        # Keep disjoint solids as a legal STEP compound.  Global Boolean fusion
        # is unnecessary for training geometry and scales poorly with profiles.
        for track in s.get("hole_tracks", []):
            cutter = loft(track)
            cut_outer = []
            for solid in outer:
                try:
                    cut_outer.append(solid.cut(cutter))
                except Exception:
                    cut_outer.append(solid)
            outer = cut_outer
        result = outer[0] if len(outer) == 1 else cq.Compound.makeCompound(outer)
    elif kind == "box":
        xdir = [B[i][0] for i in range(3)]
        axis = [B[i][2] for i in range(3)]
        origin = [center[i] + s["mins"][0]*B[i][0] + s["mins"][1]*B[i][1] + s["mins"][2]*B[i][2] for i in range(3)]
        plane = cq.Plane(origin=origin, xDir=xdir, normal=axis)
        dx=s["maxs"][0]-s["mins"][0]; dy=s["maxs"][1]-s["mins"][1]; dz=s["maxs"][2]-s["mins"][2]
        result = cq.Workplane(plane).rect(dx,dy,centered=False).extrude(dz)
    elif kind == "cylinder":
        xdir = [B[i][0] for i in range(3)]
        axis = [B[i][2] for i in range(3)]
        origin = [center[i] + s["zmin"] * axis[i] for i in range(3)]
        plane = cq.Plane(origin=origin, xDir=xdir, normal=axis)
        result = cq.Workplane(plane).circle(s["radius"]).extrude(s["zmax"]-s["zmin"])
    else:
        raise ValueError(kind)
    cq.exporters.export(result, str(OUT / "reconstructed.step"))
    cq.exporters.export(result, str(OUT / "reconstructed.stl"), tolerance=0.001, angularTolerance=0.05)
    return result

if __name__ == "__main__":
    build()
